-- Additive public SES list-price contract. No policy is installed or activated.
-- The old policy fiscal_basis column remains compatibility-only; pricing_basis is authoritative.
-- Existing quote columns and immutable fingerprints are untouched. Old readers cannot label a new public policy as invoice cost.
ALTER TABLE trusted_delivery_costs ADD COLUMN pricing_basis TEXT NOT NULL DEFAULT 'qualified_final_variable_cost' CHECK(pricing_basis IN ('qualified_final_variable_cost','public_list_price_ex_tax'));
DROP TRIGGER immutable_delivery_cost;
CREATE TRIGGER immutable_delivery_cost BEFORE UPDATE ON trusted_delivery_costs WHEN NEW.pricing_basis IS NOT OLD.pricing_basis OR NEW.id IS NOT OLD.id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.sender_id IS NOT OLD.sender_id OR NEW.channel IS NOT OLD.channel OR NEW.provider IS NOT OLD.provider OR NEW.account_id IS NOT OLD.account_id OR NEW.route_id IS NOT OLD.route_id OR NEW.options_json IS NOT OLD.options_json OR NEW.rate_json IS NOT OLD.rate_json OR NEW.base_numerator IS NOT OLD.base_numerator OR NEW.byte_numerator IS NOT OLD.byte_numerator OR NEW.rate_denominator IS NOT OLD.rate_denominator OR NEW.currency IS NOT OLD.currency OR NEW.fiscal_basis IS NOT OLD.fiscal_basis OR NEW.quote_ttl_seconds IS NOT OLD.quote_ttl_seconds OR NEW.source_reference IS NOT OLD.source_reference OR NEW.source_sha256 IS NOT OLD.source_sha256 OR NEW.valid_from IS NOT OLD.valid_from OR NEW.expires_at IS NOT OLD.expires_at OR NEW.created_at IS NOT OLD.created_at OR (OLD.status='revoked' AND NEW.status<>'revoked') BEGIN SELECT RAISE(ABORT,'immutable_delivery_cost'); END;
CREATE TRIGGER qualified_public_email_price BEFORE INSERT ON trusted_delivery_costs BEGIN SELECT RAISE(ABORT,'public_email_price_invalid') WHERE (NEW.pricing_basis='public_list_price_ex_tax' AND COALESCE((NEW.channel='email' AND NEW.provider='ses' AND NEW.options_json='{}' AND json_extract(NEW.rate_json,'$.attachmentBasis')='no_attachments' AND NEW.byte_numerator=0 AND json_extract(NEW.rate_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(NEW.rate_json,'$.plan')='Essentials' AND json_extract(NEW.rate_json,'$.tier')='0-10000000' AND json_extract(NEW.rate_json,'$.unit')='recipient' AND json_extract(NEW.rate_json,'$.currency')='USD' AND json_extract(NEW.rate_json,'$.tariffSource')='https://aws.amazon.com/ses/pricing/' AND json_extract(NEW.rate_json,'$.fxBasis')='commercial_fixed_reference' AND json_extract(NEW.rate_json,'$.fxSource')='https://www.ecb.europa.eu/stats/eurofxref/eurofxref-daily.xml' AND json_type(NEW.rate_json,'$.usdMicrosPerMessage')='integer' AND json_extract(NEW.rate_json,'$.usdMicrosPerMessage')>0 AND json_type(NEW.rate_json,'$.tariffDate')='text' AND json_extract(NEW.rate_json,'$.tariffDate')=date(json_extract(NEW.rate_json,'$.tariffDate')) AND length(json_extract(NEW.rate_json,'$.tariffDate'))=10 AND json_extract(NEW.rate_json,'$.tariffDate')<=substr(NEW.valid_from,1,10) AND json_type(NEW.rate_json,'$.fxDate')='text' AND json_extract(NEW.rate_json,'$.fxDate')=date(json_extract(NEW.rate_json,'$.fxDate')) AND length(json_extract(NEW.rate_json,'$.fxDate'))=10 AND json_extract(NEW.rate_json,'$.fxDate')<=substr(NEW.valid_from,1,10)),0)=0) OR (NEW.pricing_basis='qualified_final_variable_cost' AND json_type(NEW.rate_json,'$.pricingBasis') IS NOT NULL); END;
DROP VIEW valid_live_delivery_quotes;
CREATE VIEW valid_live_delivery_quotes AS SELECT q.*,p.valid_from AS policy_valid_from,p.expires_at AS policy_expires_at FROM live_delivery_quotes q JOIN dispatches d ON d.organization_id=q.organization_id AND d.id=q.dispatch_id JOIN trusted_delivery_costs p ON p.organization_id=q.organization_id AND p.id=q.policy_id JOIN senders s ON s.organization_id=d.organization_id AND s.id=d.sender_id LEFT JOIN documents doc ON doc.organization_id=d.organization_id AND doc.id=d.document_id WHERE d.mode='production' AND d.channel=q.channel AND d.quote_fingerprint=q.fingerprint AND d.fingerprint=q.dispatch_fingerprint AND p.status='qualified' AND p.sender_id=d.sender_id AND p.channel=d.channel AND p.provider=q.provider AND p.account_id=q.account_id AND p.route_id=q.route_id AND s.status='verified' AND s.mode='production' AND s.channel=d.channel AND s.address=d.sender_address AND (d.document_id IS NULL OR (doc.status='ready' AND doc.sha256=json_extract(q.input_json,'$.documentSha256'))) AND q.attachment_bytes=COALESCE(doc.size,0) AND q.amount_minor=d.estimated_minor AND q.ceiling_minor=d.ceiling_minor AND q.currency=d.currency AND q.source_reference=p.source_reference AND q.source_sha256=p.source_sha256 AND q.fiscal_basis=p.pricing_basis AND (p.pricing_basis='qualified_final_variable_cost' OR (json_extract(q.input_json,'$.pricingBasis')='public_list_price_ex_tax' AND json_extract(q.input_json,'$.fx.numerator')=json_extract(p.rate_json,'$.eurPerUsdNumerator') AND json_extract(q.input_json,'$.fx.denominator')=json_extract(p.rate_json,'$.eurPerUsdDenominator') AND json_extract(q.input_json,'$.fx.date')=json_extract(p.rate_json,'$.fxDate') AND json_extract(q.input_json,'$.fx.source')=json_extract(p.rate_json,'$.fxSource'))) AND q.expires_at<=p.expires_at AND q.expires_at<=strftime('%Y-%m-%dT%H:%M:%fZ',q.created_at,'+'||p.quote_ttl_seconds||' seconds') AND json_extract(q.input_json,'$.channel') IS d.channel AND json_extract(q.input_json,'$.recipient') IS d.recipient_json AND json_extract(q.input_json,'$.documentId') IS d.document_id AND json_extract(q.input_json,'$.senderId') IS d.sender_id AND json_extract(q.input_json,'$.senderAddress') IS d.sender_address AND json_extract(q.input_json,'$.subject') IS d.subject AND json_extract(q.input_json,'$.html') IS d.html AND json_extract(q.input_json,'$.text') IS d.text AND json_extract(q.input_json,'$.options') IS d.options_json AND json_extract(q.input_json,'$.campaignId') IS d.campaign_id AND json_extract(q.input_json,'$.estimatedMinor') IS d.estimated_minor AND json_extract(q.input_json,'$.ceilingMinor') IS d.ceiling_minor AND json_extract(q.input_json,'$.currency') IS d.currency AND json_extract(q.input_json,'$.mode') IS d.mode AND ((d.channel='email' AND (json_extract(p.rate_json,'$.attachmentBasis')='raw_pdf_bytes' OR (json_extract(p.rate_json,'$.attachmentBasis')='no_attachments' AND d.document_id IS NULL AND q.attachment_bytes=0 AND p.byte_numerator=0 AND json_type(p.rate_json,'$.usdMicrosPerGb') IS NULL AND json_type(p.rate_json,'$.bytesPerGb') IS NULL)) AND p.options_json=d.options_json AND q.provider_draft_id IS NULL AND q.prepared_letter_id IS NULL AND q.supplier_numerator=CAST(p.base_numerator+p.byte_numerator*q.attachment_bytes AS TEXT) AND q.supplier_denominator=CAST(p.rate_denominator AS TEXT) AND q.supplier_nanoeur=(p.base_numerator+p.byte_numerator*q.attachment_bytes+p.rate_denominator-1)/p.rate_denominator AND q.evidence_sha256=p.source_sha256) OR (d.channel='postal' AND doc.id IS NOT NULL AND q.supplier_nanoeur%10000000=0 AND q.supplier_numerator=CAST(q.supplier_nanoeur AS TEXT) AND q.supplier_denominator='1' AND EXISTS(SELECT 1 FROM provider_drafts pd WHERE pd.organization_id=d.organization_id AND pd.id=q.provider_draft_id AND pd.provider='pingen' AND pd.status='prepared' AND pd.provider_id=q.prepared_letter_id AND pd.document_id=doc.id AND pd.document_sha256=doc.sha256 AND pd.sender_id=s.id AND pd.sender_address=s.address AND pd.recipient_json=d.recipient_json AND pd.options_json=p.options_json AND pd.ceiling_minor=d.ceiling_minor AND pd.currency=d.currency AND (pd.claimed_dispatch_id IS NULL OR pd.claimed_dispatch_id=d.id) AND json_extract(d.options_json,'$.providerDraftId')=pd.id AND json_extract(d.options_json,'$.preparedLetterId')=pd.provider_id AND json_extract(d.options_json,'$.expectedAddress')=pd.expected_address AND json_extract(d.options_json,'$.addressPosition')=json_extract(pd.options_json,'$.addressPosition') AND json_extract(d.options_json,'$.deliveryProduct')=json_extract(pd.options_json,'$.deliveryProduct') AND json_extract(d.options_json,'$.printMode')=json_extract(pd.options_json,'$.printMode') AND json_extract(d.options_json,'$.printSpectrum')=json_extract(pd.options_json,'$.printSpectrum'))));
